<template><div class="schedule-picker"><div class="pickrow" role="group" aria-label="选择重复频率"><el-button v-for="item in modes" :key="item.value" :type="value.mode===item.value?'primary':'default'" plain @click="patch({mode:item.value})">{{item.label}}</el-button></div><div class="fields"><el-select v-if="value.mode==='weekly'" :model-value="value.weekday" aria-label="选择星期" @update:model-value="patch({weekday:$event})"><el-option v-for="item in weekdays" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-select v-if="value.mode==='monthly'" :model-value="value.monthDay" aria-label="选择日期" @update:model-value="patch({monthDay:$event})"><el-option v-for="day in 28" :key="day" :label="`${day} 日`" :value="day"/></el-select><el-select v-if="value.mode==='interval'" :model-value="value.intervalHours" aria-label="选择间隔" @update:model-value="patch({intervalHours:$event})"><el-option v-for="hour in 12" :key="hour" :label="`每 ${hour} 小时`" :value="hour"/></el-select><el-select :model-value="value.hour" aria-label="选择小时" @update:model-value="patch({hour:$event})"><el-option v-for="item in HOURS" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-select :model-value="value.minute" aria-label="选择分钟" @update:model-value="patch({minute:$event})"><el-option v-for="item in MINUTES" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-select :model-value="value.timezone" aria-label="选择时区" @update:model-value="patch({timezone:$event})"><el-option v-for="item in TIMEZONES" :key="item" :label="item" :value="item"/></el-select></div></div></template>
<script setup lang="ts">import{HOURS,MINUTES,TIMEZONES}from'@/constants/options';export type ScheduleValue={mode:string;hour:number;minute:number;weekday:number;monthDay:number;intervalHours:number;timezone:string};const props=defineProps<{value:ScheduleValue}>();const emit=defineEmits<{(e:'change',value:ScheduleValue):void}>();const modes=[{label:'每天',value:'daily'},{label:'每周',value:'weekly'},{label:'每月',value:'monthly'},{label:'自定义间隔',value:'interval'}],weekdays=[{label:'周日',value:0},{label:'周一',value:1},{label:'周二',value:2},{label:'周三',value:3},{label:'周四',value:4},{label:'周五',value:5},{label:'周六',value:6}];function patch(next:Partial<ScheduleValue>){emit('change',{...props.value,...next})}</script>
<style scoped>.schedule-picker{display:grid;gap:16px}.pickrow,.fields{display:flex;gap:8px;flex-wrap:wrap}.fields .el-select{width:145px}</style>
